{
  "title": "add-is-bytes-like-helper",
  "request": "hey, can you add a tiny helper called is_bytes_like to mcp.shared._compat that returns True for bytes or bytearray objects? i need it for some type checks.",
  "edits": [
    {
      "path": "src/mcp/shared/_compat.py",
      "search": "import sys",
      "replace": "import sys

def is_bytes_like(obj: object) -> bool:
    """Return ``True`` if *obj* is a ``bytes`` or ``bytearray`` instance.

    This helper is useful for quick checks without importing ``typing`` helpers.
    """
    return isinstance(obj, (bytes, bytearray))"
    }
  ],
  "test_path": "tests/test_is_bytes_like.py",
  "test": "import pytest

from mcp.shared import _compat

@pytest.mark.parametrize(
    "value,expected",
    [
        (b"abc", True),
        (bytearray(b"def"), True),
        ("string", False),
        (123, False),
        (None, False),
    ],
)
def test_is_bytes_like(value, expected):
    assert _compat.is_bytes_like(value) is expected
"
